current.custom_css:
body .m-quantity {
  border-radius: 0;
}
.m-button.m-button--link {
--btn-link-border: 1px;
}
.m-header__logo {
  padding: 30px 0 10px;
}
.m-custom-product-tabs .m-section__tabs .m-tab-header {
  font-family: "M-Heading-Font";
  font-size: 40px;
  line-height: 1.3;
}
.m-custom-product-tabs .m-section__tabs {
  margin-top: 0 !important;
}
.m-product-card__title,
.m-custom-promotion .m-icon-box__content h3 {
  font-family: "M-Body-Font";
  font-weight: 400;
}
.m-section__subheading {
  letter-spacing: 0.2em;
  font-weight: 400;
}
.m-custom-promotion .m-button.m-button--link,
.m-custom-image-with-text .m-button.m-button--link {
  padding-left: 10px !important;
  padding-right: 10px !important;
  padding-bottom: 5px !important;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-size: 15px;
}
body:not(.template-index) .m-footer {
  border-top: 1px solid rgb(var(--color-border));
}
.m-footer--block .m-footer--block-title {
  font-size: 24px !important;
}
.m-footer--block-newsletter .m-footer--block-title {
  font-family: "M-Body-Font";
  font-weight: 400;
}
@media screen and (min-width: 768px) {
  .m-footer--block-newsletter .m-footer--block-title {
    font-size: 36px !important;
  }
}
@media screen and (min-width: 1280px) {
  .m-custom-collection-list .m-collection-card__image {
    width: 150px;
    height: 150px;
    margin: 0 auto;
  }
}
